#!/usr/bin/env python3
"""kubeadd - import, list and delete contexts in your kubeconfig.

Runs on macOS, Linux and Windows. The only requirements are Python 3.8+ and
kubectl: kubeconfig files are read and written through `kubectl config view`,
so no YAML library (or yq) is needed.
"""

import argparse
import copy
import datetime
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.parse import urlparse

__version__ = "2.0.0"

# Context names generated by cloud CLIs are long; these patterns extract the
# short cluster name so it can be offered as the default context name.
EKS_ARN = re.compile(r"^arn:aws[\w-]*:eks:(?P<region>[^:]+):(?P<account>\d+):cluster/(?P<cluster>.+)$")
GKE_NAME = re.compile(r"^gke_[^_]+_[^_]+_(?P<cluster>.+)$")  # gcloud container clusters get-credentials

# Placeholders accepted by --name-format.
NAME_FORMAT_FIELDS = ("cluster", "region", "account", "profile")


class KubeaddError(Exception):
    """An error reported to the user without a traceback."""


class Cancelled(Exception):
    """The user aborted the operation."""


# --------------------------------------------------------------------------
# Console helpers
# --------------------------------------------------------------------------

def setup_console():
    # Windows consoles may default to a legacy code page that cannot print emoji.
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding="utf-8", errors="replace")
        except (AttributeError, ValueError):
            pass


def info(message=""):
    print(message)


def warn(message):
    print(f"⚠️  {message}")


def error(message):
    print(f"❌ {message}", file=sys.stderr)


def ask(prompt, default=""):
    suffix = f" [{default}]" if default else ""
    try:
        answer = input(f"{prompt}{suffix}: ").strip()
    except EOFError:
        raise Cancelled("no input available (use -y for non-interactive mode)")
    return answer or default


def ask_name(prompt, default=""):
    while True:
        name = ask(prompt, default)
        if name:
            return name
        print("   A name is required.")


def confirm(prompt, default=False):
    hint = "Y/n" if default else "y/N"
    while True:
        answer = ask(f"{prompt} ({hint})").lower()
        if not answer:
            return default
        if answer in ("y", "yes"):
            return True
        if answer in ("n", "no"):
            return False
        print("   Please answer y or n.")


def parse_selection(text, names):
    """Turn '2', '1,3', '1-3', 'all' or entry names into indexes of `names`."""
    text = text.strip()
    if text in names:
        return [names.index(text)]
    if text.lower() in ("all", "*"):
        return list(range(len(names)))
    indexes = []
    for part in re.split(r"[,\s]+", text):
        if not part:
            continue
        span = re.fullmatch(r"(\d+)-(\d+)", part)
        if span:
            start, end = int(span.group(1)), int(span.group(2))
            if start > end:
                raise ValueError(f"invalid range '{part}'")
            numbers = range(start, end + 1)
        elif part.isdigit():
            numbers = [int(part)]
        elif part in names:
            indexes.append(names.index(part))
            continue
        else:
            raise ValueError(f"'{part}' is neither a number nor a known name")
        for number in numbers:
            if not 1 <= number <= len(names):
                raise ValueError(f"{number} is out of range (1-{len(names)})")
            indexes.append(number - 1)
    if not indexes:
        raise ValueError("nothing selected")
    return list(dict.fromkeys(indexes))


def choose(names, labels, prompt, multiple):
    """Show a numbered list and return the indexes the user picked."""
    for number, label in enumerate(labels, 1):
        print(f"   {number:>2}. {label}")
    print()
    while True:
        try:
            picked = parse_selection(ask(prompt), names)
        except ValueError as exc:
            print(f"   {exc}")
            continue
        if not multiple and len(picked) > 1:
            print("   Please pick a single entry.")
            continue
        return picked


# --------------------------------------------------------------------------
# Kubeconfig access
# --------------------------------------------------------------------------

def kubectl(*args):
    executable = shutil.which("kubectl")
    if not executable:
        raise KubeaddError("kubectl is not installed or not in PATH")
    proc = subprocess.run([executable, *args], capture_output=True, encoding="utf-8")
    if proc.returncode != 0:
        raise KubeaddError(f"kubectl {' '.join(args[:2])} failed: {proc.stderr.strip()}")
    return proc.stdout


def aws(*args, profile=None, check=True):
    """Run the AWS CLI; with check=False failures return an empty string."""
    executable = shutil.which("aws")
    if not executable:
        raise KubeaddError("The AWS CLI is not installed or not in PATH (it is needed for --eks)")
    command = [executable, *args]
    if profile:
        command += ["--profile", profile]
    proc = subprocess.run(command, capture_output=True, encoding="utf-8")
    if proc.returncode == 0:
        return proc.stdout
    if not check:
        return ""
    message = proc.stderr.strip()
    hint = ""
    if "sso" in message.lower() or "expired" in message.lower():
        hint = f"\n   Try: aws sso login{f' --profile {profile}' if profile else ''}"
    elif "Unable to locate credentials" in message:
        hint = "\n   Configure credentials with 'aws configure' or pick a profile with --profile"
    raise KubeaddError(f"aws {' '.join(args[:2])} failed: {message}{hint}")


def default_target():
    """The kubeconfig kubectl itself would write to: first $KUBECONFIG entry or ~/.kube/config."""
    for path in os.environ.get("KUBECONFIG", "").split(os.pathsep):
        if path.strip():
            return os.path.abspath(os.path.expanduser(path.strip()))
    return os.path.join(os.path.expanduser("~"), ".kube", "config")


def load_kubeconfig(path, flatten=False):
    """Parse a kubeconfig file. With flatten, referenced cert/key files are embedded."""
    args = ["config", "view", "--raw", "-o", "json", f"--kubeconfig={path}"]
    if flatten:
        args.append("--flatten")
    cfg = json.loads(kubectl(*args))
    for key in ("clusters", "users", "contexts"):
        cfg[key] = cfg.get(key) or []
    cfg["current-context"] = cfg.get("current-context") or ""
    return cfg


def save_kubeconfig(cfg, path):
    """Write cfg to path as YAML, atomically and readable only by the owner."""
    directory = os.path.dirname(os.path.abspath(path))
    os.makedirs(directory, exist_ok=True)
    # mkstemp creates files with 0600 permissions, which the final file inherits.
    fd, json_path = tempfile.mkstemp(prefix=".kubeadd-", suffix=".json", dir=directory)
    yaml_path = None
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(cfg, handle)
        yaml_text = kubectl("config", "view", "--raw", f"--kubeconfig={json_path}")
        fd, yaml_path = tempfile.mkstemp(prefix=".kubeadd-", suffix=".yaml", dir=directory)
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(yaml_text)
        os.replace(yaml_path, path)
        yaml_path = None
    finally:
        for leftover in (json_path, yaml_path):
            if leftover and os.path.exists(leftover):
                os.remove(leftover)


def backup_file(path):
    if not os.path.isfile(path) or os.path.getsize(path) == 0:
        return None
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = f"{path}.backup.{stamp}"
    counter = 1
    while os.path.exists(backup):
        backup = f"{path}.backup.{stamp}_{counter}"
        counter += 1
    shutil.copy2(path, backup)
    return backup


def write_kubeconfig(cfg, path, dry_run):
    if dry_run:
        info("🧪 Dry run: nothing was written")
        return
    backup = backup_file(path)
    if backup:
        info(f"💾 Backup created: {backup}")
    save_kubeconfig(cfg, path)


def find(cfg, kind, name):
    """Find a 'cluster', 'user' or 'context' entry by name."""
    return next((entry for entry in cfg[kind + "s"] if entry.get("name") == name), None)


def put(cfg, kind, name, body):
    entries = cfg[kind + "s"]
    entry = {"name": name, kind: body}
    for index, existing in enumerate(entries):
        if existing.get("name") == name:
            entries[index] = entry
            return
    entries.append(entry)


def remove(cfg, kind, name):
    cfg[kind + "s"][:] = [entry for entry in cfg[kind + "s"] if entry.get("name") != name]


def contexts_using(cfg, kind, name):
    """Names of the contexts that reference the given cluster or user."""
    return [ctx["name"] for ctx in cfg["contexts"] if (ctx.get("context") or {}).get(kind) == name]


def prune_orphans(cfg, clusters, users):
    """Remove the given clusters/users if no context references them any more."""
    removed = []
    for kind, names in (("cluster", clusters), ("user", users)):
        for name in dict.fromkeys(names):
            if name and find(cfg, kind, name) and not contexts_using(cfg, kind, name):
                remove(cfg, kind, name)
                removed.append((kind, name))
    return removed


def server_of(cfg, ctx):
    cluster = find(cfg, "cluster", (ctx.get("context") or {}).get("cluster"))
    return ((cluster or {}).get("cluster") or {}).get("server", "-")


def suggest_name(name):
    for pattern in (EKS_ARN, GKE_NAME):
        match = pattern.match(name)
        if match:
            return match.group("cluster")
    return name


def check_server_url(url):
    """Return why url is not a usable API server URL, or None if it is fine."""
    try:
        parsed = urlparse(url)
        parsed.port  # raises ValueError for a malformed port
    except ValueError:
        return "invalid port"
    if parsed.scheme not in ("https", "http") or not parsed.hostname:
        return "expected https://server-address[:port][/path]"
    return None


# --------------------------------------------------------------------------
# kubeadd -f: import contexts
# --------------------------------------------------------------------------

def source_contexts(cfg, path):
    if cfg["contexts"]:
        return cfg["contexts"]
    # Some generated files only carry a cluster and a user; pair them up.
    if len(cfg["clusters"]) == 1 and len(cfg["users"]) <= 1:
        cluster = cfg["clusters"][0]["name"]
        user = cfg["users"][0]["name"] if cfg["users"] else ""
        return [{"name": cluster, "context": {"cluster": cluster, "user": user}}]
    if not cfg["clusters"]:
        raise KubeaddError(f"'{path}' does not contain any clusters")
    raise KubeaddError(f"'{path}' has no contexts, so it is unclear which user belongs to which cluster")


def conflict_action(cfg, kind, name, args, interactive):
    """Decide what to do when a different entry with this name already exists.

    Returns ("overwrite", name), ("rename", new_name) or ("skip", name).
    """
    used_by = contexts_using(cfg, kind, name) if kind != "context" else []
    detail = f" (used by: {', '.join(used_by)})" if used_by else ""
    if args.overwrite:
        warn(f"Overwriting existing {kind} '{name}'{detail}")
        return "overwrite", name
    if not interactive:
        raise KubeaddError(
            f"{kind.capitalize()} '{name}' already exists in the target kubeconfig with different settings{detail}. "
            "Use --overwrite or choose another name."
        )
    warn(f"{kind.capitalize()} '{name}' already exists with different settings{detail}.")
    while True:
        answer = ask("   [o]verwrite, [r]ename, [s]kip this context or [a]bort?").lower()
        if answer in ("o", "overwrite"):
            return "overwrite", name
        if answer in ("r", "rename"):
            return "rename", ask_name(f"   New {kind} name")
        if answer in ("s", "skip"):
            return "skip", name
        if answer in ("a", "abort"):
            raise Cancelled()


def resolve_name(cfg, kind, name, body, args, interactive, accepted):
    """Final name for a cluster/user entry, or None if the context should be skipped.

    `accepted` holds (kind, name) pairs the user already agreed to overwrite.
    """
    while True:
        existing = find(cfg, kind, name)
        if existing is None or existing.get(kind) == body:
            return name
        if (kind, name) in accepted:
            info(f"   Replacing {kind} '{name}'")
            return name
        action, new_name = conflict_action(cfg, kind, name, args, interactive)
        if action == "overwrite":
            return name
        if action == "skip":
            return None
        name = new_name


def import_context(src, ctx, cfg, args, interactive, imported_names, default, confirm_server):
    """Copy one context with its cluster and user from src into cfg.

    Returns (context, cluster, user) names, or None if the context was skipped.
    """
    body = dict(ctx.get("context") or {})
    cluster = find(src, "cluster", body.get("cluster"))
    if cluster is None:
        warn(f"Skipping '{ctx['name']}': cluster '{body.get('cluster')}' is not defined in the file")
        return None
    user = find(src, "user", body["user"]) if body.get("user") else None
    if body.get("user") and user is None:
        warn(f"Skipping '{ctx['name']}': user '{body['user']}' is not defined in the file")
        return None
    cluster_body = dict(cluster.get("cluster") or {})

    info("📋 Found context:")
    info(f"   Context  : {ctx['name']}")
    info(f"   Cluster  : {cluster['name']}")
    info(f"   Server   : {cluster_body.get('server', '-')}")
    info(f"   User     : {user['name'] if user else '-'}")
    if body.get("namespace"):
        info(f"   Namespace: {body['namespace']}")
    info()

    # Naming. Cluster and user default to the context name so that files which
    # all use generic names (e.g. kubeadm's "kubernetes") never collide.
    if default in imported_names:
        default = ctx["name"]
    if args.name:
        context_name = args.name
    elif interactive:
        context_name = ask_name("🏷️  Context name", default)
    else:
        context_name = default
    custom_cluster, custom_user = args.cluster_name, args.user_name
    if interactive and not (custom_cluster or custom_user):
        if confirm("   Set cluster and user names separately?", default=False):
            custom_cluster = ask_name("   Cluster name", context_name)
            if user:
                custom_user = ask_name("   User name", context_name)

    # Server URL
    server = args.server or cluster_body.get("server", "")
    if not args.server and interactive and confirm_server:
        if not confirm(f"🌐 Server URL is {server or '(empty)'} - is this correct?", default=True):
            server = ask("   Correct server URL")
    while True:
        problem = check_server_url(server)
        if not problem:
            break
        if not interactive:
            raise KubeaddError(f"Invalid server URL '{server}' in context '{ctx['name']}': {problem}")
        error(f"Invalid server URL '{server}': {problem}")
        server = ask("   Server URL")
    if server.startswith("http://"):
        warn("The server URL uses plain http; traffic to the API server will not be encrypted")
    cluster_body["server"] = server

    if args.namespace:
        body["namespace"] = args.namespace

    # Conflicts with what is already in the target kubeconfig. The context is
    # checked first so that renaming it also renames the cluster/user entries
    # that follow the context name, instead of asking three times.
    user_body = (user or {}).get("user") or {}
    accepted = set()
    while True:
        cluster_name = custom_cluster or context_name
        user_name = custom_user or context_name
        body["cluster"] = cluster_name
        if user:
            body["user"] = user_name
        existing = find(cfg, "context", context_name)
        if existing is None or (
            existing.get("context") == body
            and (find(cfg, "cluster", cluster_name) or {}).get("cluster") == cluster_body
            and (not user or (find(cfg, "user", user_name) or {}).get("user") == user_body)
        ):
            break
        action, new_name = conflict_action(cfg, "context", context_name, args, interactive)
        if action == "skip":
            info(f"⏭️  Skipped '{ctx['name']}'")
            return None
        if action == "overwrite":
            # Entries only the replaced context used can be replaced without asking again.
            old = existing.get("context") or {}
            for kind in ("cluster", "user"):
                if contexts_using(cfg, kind, old.get(kind)) == [context_name]:
                    accepted.add((kind, old.get(kind)))
            break
        context_name = new_name

    cluster_name = resolve_name(cfg, "cluster", cluster_name, cluster_body, args, interactive, accepted)
    if cluster_name is None:
        info(f"⏭️  Skipped '{ctx['name']}'")
        return None
    body["cluster"] = cluster_name
    if user:
        user_name = resolve_name(cfg, "user", user_name, user_body, args, interactive, accepted)
        if user_name is None:
            info(f"⏭️  Skipped '{ctx['name']}'")
            return None
        body["user"] = user_name

    previous = find(cfg, "context", context_name)
    put(cfg, "cluster", cluster_name, cluster_body)
    if user:
        put(cfg, "user", user_name, user_body)
    put(cfg, "context", context_name, body)
    if previous:
        # An overwritten context may leave its old cluster/user unreferenced.
        old = previous.get("context") or {}
        for kind, name in prune_orphans(cfg, [old.get("cluster")], [old.get("user")]):
            info(f"🧹 Removed {kind} '{name}' that was only used by the replaced context")
    return context_name, cluster_name, user_name if user else "-"


def cmd_add(args, target):
    source = os.path.abspath(os.path.expanduser(args.file))
    if not os.path.isfile(source):
        raise KubeaddError(f"File '{args.file}' not found")
    if os.path.exists(target) and os.path.samefile(source, target):
        raise KubeaddError("The file to import is the target kubeconfig itself")
    interactive = not args.yes

    info(f"🔍 Analyzing {source} ...")
    src = load_kubeconfig(source, flatten=True)
    contexts = source_contexts(src, source)
    names = [ctx["name"] for ctx in contexts]

    if args.contexts:
        missing = [name for name in args.contexts if name not in names]
        if missing:
            raise KubeaddError(
                f"Context(s) not found in the file: {', '.join(missing)}\n   Available: {', '.join(names)}"
            )
        selected = [contexts[names.index(name)] for name in dict.fromkeys(args.contexts)]
    elif args.all or len(contexts) == 1:
        selected = contexts
    elif not interactive:
        raise KubeaddError(
            f"The file contains {len(contexts)} contexts; pick some with --context NAME or use --all\n"
            f"   Available: {', '.join(names)}"
        )
    else:
        info(f"📚 The file contains {len(contexts)} contexts:")
        labels = [f"{ctx['name']}  ({server_of(src, ctx)})" for ctx in contexts]
        picked = choose(names, labels, "Select context(s) to import (e.g. 1,3 / 1-2 / all)", multiple=True)
        selected = [contexts[index] for index in picked]

    return import_contexts(src, selected, target, args, interactive)


def import_contexts(src, selected, target, args, interactive, default_names=None, confirm_server=True):
    """Import the selected contexts of src into the target kubeconfig and save it."""
    if len(selected) > 1 and (args.name or args.cluster_name or args.user_name or args.server):
        raise KubeaddError(
            "--name, --cluster-name, --user-name and --server can only be used when importing a single context"
        )

    info(f"📁 Target kubeconfig: {target}")
    info()
    cfg = load_kubeconfig(target)
    original = copy.deepcopy(cfg)
    imported = []
    for number, ctx in enumerate(selected, 1):
        if len(selected) > 1:
            info(f"── [{number}/{len(selected)}] {ctx['name']}")
        default_name = (default_names or {}).get(ctx["name"]) or suggest_name(ctx["name"])
        result = import_context(src, ctx, cfg, args, interactive, [entry[0] for entry in imported],
                                default_name, confirm_server)
        if result:
            imported.append(result)
        info()

    if not imported:
        info("Nothing was imported.")
        return 1

    new_names = [entry[0] for entry in imported]
    switch_to = None
    if args.switch:
        switch_to = new_names[0]
    elif args.switch is None and cfg["current-context"] not in new_names:
        if not interactive:
            switch_to = new_names[0] if len(new_names) == 1 else None
        elif len(new_names) == 1:
            if confirm(f"🎯 Switch current context to '{new_names[0]}'?", default=True):
                switch_to = new_names[0]
        elif confirm("🎯 Switch current context to one of the imported contexts?", default=False):
            switch_to = new_names[choose(new_names, new_names, "Context to switch to", multiple=False)[0]]
    if switch_to:
        cfg["current-context"] = switch_to

    if cfg == original:
        info("✅ Kubeconfig is already up to date, nothing to change")
        return 0
    write_kubeconfig(cfg, target, args.dry_run)
    for context_name, cluster_name, user_name in imported:
        info(f"✅ Context '{context_name}' (cluster: {cluster_name}, user: {user_name})")
    if switch_to:
        info(f"🎯 Current context: {switch_to}")
    else:
        info(f"🎯 Switch with: kubectl config use-context {new_names[0]}")
    return 0


# --------------------------------------------------------------------------
# kubeadd --eks: import EKS clusters via `aws eks update-kubeconfig`
# --------------------------------------------------------------------------

def check_name_format(name_format):
    try:
        name_format.format_map({field: "x" for field in NAME_FORMAT_FIELDS})
    except (KeyError, ValueError, IndexError):
        fields = " ".join(f"{{{field}}}" for field in NAME_FORMAT_FIELDS)
        raise KubeaddError(f"Invalid --name-format '{name_format}'; available placeholders: {fields}")


def eks_context_name(name_format, context_name, profile):
    match = EKS_ARN.match(context_name)
    if not match:
        return suggest_name(context_name)
    return name_format.format_map(dict(match.groupdict(), profile=profile))


def pick_profile(args, interactive):
    """The --profile to pass to the AWS CLI; None means the CLI's own default."""
    if args.profile:
        return args.profile
    if os.environ.get("AWS_PROFILE") or not interactive:
        return None
    profiles = aws("configure", "list-profiles", check=False).split()
    if len(profiles) <= 1:
        return None
    info("👤 AWS profiles:")
    return profiles[choose(profiles, profiles, "Select profile", multiple=False)[0]]


def pick_regions(args, profile, interactive):
    if args.region:
        return [args.region]
    configured = (
        os.environ.get("AWS_REGION")
        or os.environ.get("AWS_DEFAULT_REGION")
        or aws("configure", "get", "region", profile=profile, check=False).strip()
    )
    if args.all_regions:
        output = aws("ec2", "describe-regions", "--region", configured or "us-east-1",
                     "--query", "Regions[].RegionName", "--output", "json", profile=profile)
        return sorted(json.loads(output))
    if configured:
        info(f"🌍 Region: {configured} (change with --region or --all-regions)")
        return [configured]
    if interactive:
        return [ask_name("🌍 AWS region (e.g. eu-west-1)")]
    raise KubeaddError("No AWS region configured; use --region or --all-regions")


def list_clusters(profile, regions):
    """Return (cluster, region) pairs for every EKS cluster in the given regions."""
    def clusters_in(region):
        output = aws("eks", "list-clusters", "--region", region, "--output", "json", profile=profile)
        return [(name, region) for name in json.loads(output).get("clusters", [])]

    info(f"🔍 Looking for EKS clusters in {len(regions)} region(s) ...")
    if len(regions) == 1:
        return clusters_in(regions[0])
    found, failures = [], []
    with ThreadPoolExecutor(max_workers=8) as pool:
        futures = {pool.submit(clusters_in, region): region for region in regions}
        for future in as_completed(futures):
            try:
                found.extend(future.result())
            except KubeaddError as exc:
                failures.append((futures[future], exc))
    if failures and len(failures) == len(regions):
        raise failures[0][1]  # e.g. expired credentials: one message is enough
    for region, exc in failures:
        warn(f"{region}: {exc}")
    return sorted(found, key=lambda pair: (pair[1], pair[0]))


def pick_clusters(args, profile, regions, interactive):
    """Return the (cluster, region) pairs to import."""
    if args.eks and len(regions) == 1:
        return [(name, regions[0]) for name in dict.fromkeys(args.eks)]
    found = list_clusters(profile, regions)
    if args.eks:
        selected = [pair for pair in found if pair[0] in args.eks]
        missing = [name for name in args.eks if name not in {pair[0] for pair in selected}]
        if missing:
            raise KubeaddError(f"EKS cluster(s) not found: {', '.join(missing)}")
        return selected
    if not found:
        raise KubeaddError(f"No EKS clusters found in {', '.join(regions)}")
    if args.all or len(found) == 1:
        return found
    if not interactive:
        raise KubeaddError(
            f"Found {len(found)} clusters; name them (kubeadd --eks NAME ...) or use --all\n"
            f"   Available: {', '.join(f'{name} ({region})' for name, region in found)}"
        )
    info(f"☸️  Found {len(found)} EKS clusters:")
    labels = [f"{name}  ({region})" for name, region in found]
    picked = choose([name for name, _ in found], labels, "Select cluster(s) to import (e.g. 1,3 / 1-2 / all)",
                    multiple=True)
    return [found[index] for index in picked]


def cmd_eks(args, target):
    interactive = not args.yes
    profile = pick_profile(args, interactive)
    regions = pick_regions(args, profile, interactive)
    clusters = pick_clusters(args, profile, regions, interactive)

    # Let the AWS CLI write the exec-based credentials into a scratch file and
    # import from there, so naming, conflicts and backups work exactly as with -f.
    workdir = tempfile.mkdtemp(prefix="kubeadd-eks-")
    try:
        generated = os.path.join(workdir, "config")
        for name, region in clusters:
            info(f"☁️  Fetching {name} ({region}) ...")
            command = ["eks", "update-kubeconfig", "--name", name, "--region", region, "--kubeconfig", generated]
            if args.role_arn:
                command += ["--role-arn", args.role_arn]
            aws(*command, profile=profile)
        info()
        src = load_kubeconfig(generated, flatten=True)
        profile_label = profile or os.environ.get("AWS_PROFILE") or "default"
        default_names = {
            ctx["name"]: eks_context_name(args.name_format or "{cluster}", ctx["name"], profile_label)
            for ctx in src["contexts"]
        }
        return import_contexts(src, src["contexts"], target, args, interactive, default_names, confirm_server=False)
    finally:
        shutil.rmtree(workdir, ignore_errors=True)


# --------------------------------------------------------------------------
# kubeadd -d: delete contexts
# --------------------------------------------------------------------------

def cmd_delete(args, target):
    if not os.path.isfile(target):
        raise KubeaddError(f"Kubeconfig file not found at {target}")
    cfg = load_kubeconfig(target)
    names = [ctx["name"] for ctx in cfg["contexts"]]
    if not names:
        raise KubeaddError(f"No contexts found in {target}")
    info(f"📁 Kubeconfig: {target}")

    if args.delete:
        missing = [name for name in args.delete if name not in names]
        if missing:
            raise KubeaddError(
                f"Context(s) not found: {', '.join(missing)}\n   Available: {', '.join(names)}"
            )
        selected = list(dict.fromkeys(args.delete))
    elif args.yes:
        raise KubeaddError("Name the context(s) to delete when using -y, e.g. kubeadd -d my-cluster -y")
    else:
        info("🗑️  Contexts:")
        labels = [
            f"{ctx['name']}  ({server_of(cfg, ctx)})" + ("  [current]" if ctx["name"] == cfg["current-context"] else "")
            for ctx in cfg["contexts"]
        ]
        picked = choose(names, labels, "Select context(s) to delete (e.g. 1,3 / 1-2)", multiple=True)
        selected = [names[index] for index in picked]

    clusters, users = [], []
    for name in selected:
        body = find(cfg, "context", name).get("context") or {}
        clusters.append(body.get("cluster"))
        users.append(body.get("user"))
        remove(cfg, "context", name)
    removed = prune_orphans(cfg, clusters, users)

    info()
    info("⚠️  The following entries will be removed:")
    for name in selected:
        info(f"   context  {name}")
    for kind, name in removed:
        info(f"   {kind:<8} {name}")
    for kind, names_ in (("cluster", clusters), ("user", users)):
        for name in dict.fromkeys(names_):
            if name and (kind, name) not in removed and find(cfg, kind, name):
                info(f"   (keeping {kind} '{name}', still used by: {', '.join(contexts_using(cfg, kind, name))})")
    if cfg["current-context"] in selected:
        info("   current-context will be unset")
        cfg["current-context"] = ""

    if not args.yes and not confirm("Are you sure?", default=False):
        raise Cancelled()
    write_kubeconfig(cfg, target, args.dry_run)
    info(f"✅ Deleted {len(selected)} context(s)")
    return 0


# --------------------------------------------------------------------------
# kubeadd -l: list contexts
# --------------------------------------------------------------------------

def cmd_list(target):
    cfg = load_kubeconfig(target)
    info(f"📁 Kubeconfig: {target}")
    if not cfg["contexts"]:
        info("No contexts found.")
        return 0
    rows = [("", "CONTEXT", "CLUSTER", "USER", "NAMESPACE", "SERVER")]
    for ctx in cfg["contexts"]:
        body = ctx.get("context") or {}
        rows.append((
            "*" if ctx["name"] == cfg["current-context"] else "",
            ctx["name"],
            body.get("cluster") or "-",
            body.get("user") or "-",
            body.get("namespace") or "-",
            server_of(cfg, ctx),
        ))
    widths = [max(len(row[column]) for row in rows) for column in range(len(rows[0]))]
    for row in rows:
        info("  ".join(value.ljust(width) for value, width in zip(row, widths)).rstrip())
    return 0


# --------------------------------------------------------------------------
# CLI
# --------------------------------------------------------------------------

EXAMPLES = """\
examples:
  kubeadd -f ~/Downloads/new-cluster.yaml          import interactively
  kubeadd -f clusters.yaml -c dev -c staging -y    import two contexts with default names
  kubeadd -f admin.conf -n lab --cluster-name lab-cluster --user-name lab-admin -y
  kubeadd --eks                                    pick AWS profile, region and EKS clusters
  kubeadd --eks prod --profile acme --region eu-west-1 --name-format '{profile}-{cluster}'
  kubeadd --eks --profile acme --all-regions --all -y
  kubeadd -l                                       list contexts
  kubeadd -d                                       pick contexts to delete
  kubeadd -d old-cluster -y                        delete without prompting
"""


def build_parser():
    parser = argparse.ArgumentParser(
        prog="kubeadd",
        description="Import, list and delete contexts in your kubeconfig.",
        epilog=EXAMPLES,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("-f", "--file", metavar="FILE", help="import context(s) from a kubeconfig file")
    mode.add_argument("--eks", nargs="*", metavar="CLUSTER",
                      help="import AWS EKS cluster(s) via the AWS CLI (pick from a list without names)")
    mode.add_argument("-d", "--delete", nargs="*", metavar="CONTEXT",
                      help="delete context(s) and their no longer used clusters/users (interactive without names)")
    mode.add_argument("-l", "--list", action="store_true", help="list the contexts in the kubeconfig")

    imports = parser.add_argument_group("import options (with -f or --eks)")
    imports.add_argument("-c", "--context", dest="contexts", action="append", metavar="NAME",
                         help="context to import from FILE; repeat for more (default: ask)")
    imports.add_argument("--all", action="store_true", help="import every context in FILE / every cluster found")
    imports.add_argument("-n", "--name", help="new context name")
    imports.add_argument("--cluster-name", help="new cluster name (default: the context name)")
    imports.add_argument("--user-name", help="new user name (default: the context name)")
    imports.add_argument("--namespace", help="default namespace for the imported context(s)")
    imports.add_argument("--server", help="override the API server URL")
    imports.add_argument("--overwrite", action="store_true", help="replace existing entries with the same name")
    switch = imports.add_mutually_exclusive_group()
    switch.add_argument("--switch", action="store_true", default=None,
                        help="make the (first) imported context the current one")
    switch.add_argument("--no-switch", dest="switch", action="store_false", help="keep the current context")
    parser.set_defaults(switch=None)  # None = ask (or decide automatically with -y)

    eks = parser.add_argument_group("EKS options (with --eks)")
    eks.add_argument("--profile", help="AWS profile (default: $AWS_PROFILE, or ask when several exist)")
    regions = eks.add_mutually_exclusive_group()
    regions.add_argument("--region", help="AWS region (default: the profile's region)")
    regions.add_argument("--all-regions", action="store_true", help="look for clusters in every enabled region")
    eks.add_argument("--role-arn", help="IAM role to assume when kubectl requests a token")
    eks.add_argument("--name-format", metavar="FORMAT",
                     help="default context name, e.g. '{profile}-{cluster}' "
                          "(placeholders: {cluster} {region} {account} {profile}; default: '{cluster}')")

    parser.add_argument("--kubeconfig", metavar="PATH",
                        help="kubeconfig to modify (default: first entry of $KUBECONFIG, else ~/.kube/config)")
    parser.add_argument("-y", "--yes", action="store_true",
                        help="never prompt: accept defaults and confirm changes")
    parser.add_argument("--dry-run", action="store_true", help="show what would change without writing anything")
    parser.add_argument("-V", "--version", action="version", version=f"%(prog)s {__version__}")
    return parser


def main(argv=None):
    setup_console()
    parser = build_parser()
    args = parser.parse_args(argv)
    import_only = (args.contexts, args.all, args.name, args.cluster_name, args.user_name,
                   args.namespace, args.server, args.overwrite, args.switch is not None)
    eks_only = (args.profile, args.region, args.all_regions, args.role_arn, args.name_format)
    if not args.file and args.eks is None and any(import_only):
        parser.error("import options can only be used together with -f or --eks")
    if args.contexts and not args.file:
        parser.error("-c/--context can only be used together with -f")
    if args.eks is None and any(eks_only):
        parser.error("--profile, --region, --all-regions, --role-arn and --name-format require --eks")
    target = os.path.abspath(os.path.expanduser(args.kubeconfig)) if args.kubeconfig else default_target()

    try:
        if args.name_format:
            check_name_format(args.name_format)
        if args.file:
            return cmd_add(args, target)
        if args.eks is not None:
            return cmd_eks(args, target)
        if args.delete is not None:
            return cmd_delete(args, target)
        if args.list:
            return cmd_list(target)
        parser.print_help()
        return 1
    except Cancelled as exc:
        error(f"Operation cancelled{f': {exc}' if str(exc) else ''}")
        return 1
    except KeyboardInterrupt:
        print()
        error("Operation cancelled")
        return 130
    except KubeaddError as exc:
        error(str(exc))
        return 1


if __name__ == "__main__":
    sys.exit(main())
